function dubbingCommunityHTML(p){
 if(p.visibility!=='public')return '';
 return `<section class="dubbing-panel dubbing-community"><div class="dubbing-section-heading"><div><span class="eyebrow">TOGETHER</span><h2>이 장면에 마음을 남겨주세요.</h2></div><button class="small-button" id="dubbing-like" aria-pressed="${!!p.community?.liked}">♥ 좋아요 ${Number(p.community?.likes)||0}</button></div><div class="dubbing-comment-layout"><div><form id="dubbing-comment-form"><label>감상 남기기<textarea name="body" rows="2" maxlength="2000" placeholder="함께 연기한 목소리에 응원을 보내주세요." required></textarea></label><button class="primary-button" type="submit">댓글 남기기</button><p class="dubbing-feedback" role="status"></p></form><div id="dubbing-comments" aria-live="polite"></div><button class="small-button" id="dubbing-comments-more" hidden>댓글 더 보기</button></div><aside class="dubbing-community-note"><h3>함께 만드는 작품</h3><p>서로의 목소리와 창작의 권리를 존중해주세요.</p>${p.isOwner?'':`<button class="small-button" data-dubbing-rights-report>권리 침해 신고</button><small>접수 내용과 연락처는 운영자에게만 전달됩니다.</small>`}</aside></div></section>`;
}
function dubbingRemovedHTML(p){
 const status={pending:'검토 중',removed:'공개 중단',appealed:'이의신청 검토 중',upheld:'공개 중단 유지',restored:'복원',dismissed:'신고 종결'};
 return `<a class="dubbing-back" href="#dubbing?tab=mine">← 내 더빙</a><header class="dubbing-heading"><span class="eyebrow">RIGHTS REVIEW</span><h1>${esc(p.title)}</h1><p>권리 신고 검토로 공개와 제작이 중단되었습니다.<br>저장된 대본과 녹음은 보존됩니다.</p></header><section class="dubbing-panel">${p.reports.map(r=>`<article class="dubbing-rights-case"><span class="dubbing-tag">${status[r.status]||'확인 중'}</span><h3>운영자 검토 안내</h3><p>${esc(r.decision||'검토 중입니다.')}</p>${r.appeal?`<p>내 이의신청: ${esc(r.appeal)}</p>`:''}${r.status==='removed'?`<button class="primary-button" data-dubbing-appeal="${esc(r.id)}" data-version="${r.version}">권리 증빙 · 이의신청</button>`:''}</article>`).join('')}</section>`;
}
function dubbingRightsForm(p,appeal=null){
 dialog(`<section class="dubbing-page"><span class="eyebrow">RIGHTS & RESPECT</span><h2>${appeal?'공개 중단 이의신청':'권리 침해 신고'}</h2><p>${esc(p.title)}</p><form id="dubbing-rights-form">${appeal?'':'<label>권리자 이름 또는 단체<input name="rightsholder" maxlength="100" required></label><label>연락 이메일<input name="contact" type="email" maxlength="254" required></label>'}<label>${appeal?'이용 권한에 대한 설명':'침해 내용과 신고 사유'}<textarea name="details" rows="4" maxlength="2000" required></textarea></label><label>증빙 링크 (줄마다 하나, 최대 5개)<textarea name="evidence" rows="2" placeholder="https://…" ${appeal?'':'required'}></textarea></label>${appeal?'':'<label class="dubbing-consent"><input name="confirmed" type="checkbox" required> 해당 권리자 또는 적법한 대리인이며, 사실에 근거해 신고합니다.</label>'}<p class="dubbing-feedback" role="status"></p><div class="dubbing-form-actions"><button class="primary-button" type="submit">${appeal?'이의신청 제출':'신고 접수'}</button><button class="small-button" type="button" data-close-rights>취소</button></div></form></section>`);
 const modal=$('#dialog'),form=$('#dubbing-rights-form');form.querySelector('[data-close-rights]').onclick=()=>modal.close();
 form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;const d=new FormData(form),body={details:d.get('details'),evidence:String(d.get('evidence')).split('\n').map(x=>x.trim()).filter(Boolean),...(appeal?{version:appeal.version}:{rightsholder:d.get('rightsholder'),contact:d.get('contact'),confirmed:d.has('confirmed')})};
  try{await api('/api/dubbing/projects/'+p.id+'/'+(appeal?'appeal/'+appeal.id:'report'),'POST',body);modal.close();toast(appeal?'이의신청을 접수했어요.':'신고를 접수했어요. 운영자가 확인합니다.');if(appeal)render();}catch(err){dubbingMessage(form,err.message);}finally{b.disabled=false;}};
}
function bindDubbingCommunity(p,root){
 const needLogin=()=>{if(me)return true;returnRoute=location.hash;location.hash='#account';return false;};
 root.querySelectorAll('[data-dubbing-appeal]').forEach(b=>b.onclick=()=>dubbingRightsForm(p,{id:b.dataset.dubbingAppeal,version:Number(b.dataset.version)}));
 const report=root.querySelector('[data-dubbing-rights-report]');if(report)report.onclick=()=>{if(needLogin())dubbingRightsForm(p);};
 const like=root.querySelector('#dubbing-like');if(like)like.onclick=async()=>{if(!needLogin())return;like.disabled=true;try{const result=await api('/api/dubbing/projects/'+p.id+'/like',p.community.liked?'DELETE':'PUT');p.community=result;like.textContent='♥ 좋아요 '+result.likes;like.setAttribute('aria-pressed',String(!!result.liked));}catch(e){toast(e.message);}finally{like.disabled=false;}};
 const list=root.querySelector('#dubbing-comments'),form=root.querySelector('#dubbing-comment-form'),more=root.querySelector('#dubbing-comments-more');if(!list)return;
 let offset=0,loading=false,pendingId=null,pendingText='';
 const load=async(append=false)=>{if(loading)return;loading=true;try{const data=await api('/api/dubbing/projects/'+p.id+'/comments?offset='+(append?offset:0));if(!list.isConnected)return;
  const html=data.comments.map(c=>`<article class="dubbing-comment"><div><b>${esc(c.name)}</b><small>${new Date(c.created*1000).toLocaleDateString('ko-KR')}</small></div><p>${esc(c.body)}</p><div class="dubbing-comment-actions">${c.canDelete?`<button class="small-button" data-comment-delete="${esc(c.id)}">삭제</button>`:''}${c.canReport?`<button class="small-button" data-comment-report="${esc(c.id)}">댓글 신고</button>`:''}</div></article>`).join('');
  if(append)list.insertAdjacentHTML('beforeend',html);else list.innerHTML=html||'<p class="dubbing-muted">첫 감상을 남겨보세요.</p>';offset=data.nextOffset;more.hidden=offset===null;
 }catch(e){toast(e.message);}finally{loading=false;}};
 more.onclick=()=>load(true);load();
 form.onsubmit=async e=>{e.preventDefault();if(!needLogin())return;const button=form.querySelector('button'),text=form.elements.body.value.trim();if(!text)return;
  if(text!==pendingText||!pendingId){pendingId=crypto.randomUUID();pendingText=text;}button.disabled=true;
  try{await api('/api/dubbing/projects/'+p.id+'/comments','POST',{id:pendingId,body:text});pendingId=null;form.reset();dubbingMessage(form,'댓글을 남겼어요.');await load();}catch(err){dubbingMessage(form,err.message);}finally{button.disabled=false;}};
 list.onclick=async e=>{const b=e.target.closest('[data-comment-delete],[data-comment-report]');if(!b)return;const deleting=!!b.dataset.commentDelete,cid=b.dataset.commentDelete||b.dataset.commentReport;
  if(deleting&&!confirm('이 댓글을 삭제할까요?'))return;
  if(!deleting){dialog(`<section class="dubbing-page"><h2>댓글 신고</h2><form id="dubbing-comment-report-form"><label>사유<select name="reason"><option value="abuse">욕설·괴롭힘</option><option value="spam">스팸</option><option value="privacy">개인정보</option><option value="sexual">음란 내용</option><option value="other">기타</option></select></label><label>상세 설명<textarea name="details" maxlength="500" rows="3"></textarea></label><p class="dubbing-feedback" role="status"></p><button class="primary-button" type="submit">신고 접수</button></form></section>`);const rf=$('#dubbing-comment-report-form');rf.onsubmit=async ev=>{ev.preventDefault();rf.querySelector('button').disabled=true;try{await api('/api/dubbing/projects/'+p.id+'/comments/'+cid+'/report','POST',{reason:rf.elements.reason.value,details:rf.elements.details.value});$('#dialog').close();toast('댓글 신고를 접수했어요.');await load();}catch(err){dubbingMessage(rf,err.message);}finally{rf.querySelector('button').disabled=false;}};return;}
  b.disabled=true;try{await api('/api/dubbing/projects/'+p.id+'/comments/'+cid,'DELETE');await load();}catch(err){toast(err.message);b.disabled=false;}};
}
